// Dependency-free checks for the static site. See CONTRIBUTING.md ("Verify").
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, statSync } from "node:fs";
import { createServer } from "node:http";
import { dirname, extname, join, normalize, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const site = join(root, "docs");
const failures = [];
const fail = (message) => failures.push(message);

const LINE_BUDGET = 2000;
// Generated by the publishers in Documents/ChatGPT/wymn; not hand-edited here.
const GENERATED = ["docs/wynncraft-addons/", "docs/wynncraft-market/"];
// Redirect stubs have no visible heading.
const NO_HEADING = ["docs/a/index.html"];

const tracked = execFileSync("git", ["ls-files", "-z"], { cwd: root, encoding: "utf8" })
  .split("\0")
  .filter((file) => file && existsSync(join(root, file)));

// Repo health
for (const doc of ["AGENTS.md", "CLAUDE.md", "CONTRIBUTING.md", "NOTES.md"]) {
  if (!existsSync(join(root, doc))) fail(`Missing ${doc}`);
}
for (const file of tracked) {
  if (!file.includes("/") && /^(ARCHITECTURE|SESSION_START|REPO_MEMORY|.*_MEMORY)\.md$/i.test(file))
    fail(`Duplicate root policy doc: ${file}`);
  if (/(^|\/)(\.tmp_|_tmp_|\.scratch\/|\.unattended_runs\/)/.test(file)) fail(`Tracked scratch file: ${file}`);
}

// Public folder hygiene and page structure
const published = tracked.filter((file) => file.startsWith("docs/"));
const textFiles = published.filter((file) => [".html", ".js", ".css", ".json", ".txt", ".md"].includes(extname(file)));
for (const file of published) {
  if (extname(file) === ".md") fail(`Notes file in the public folder: ${file}`);
}
for (const file of textFiles) {
  const text = readFileSync(join(root, file), "utf8");
  if (/[A-Za-z]:[\\/]+(?:Users|ProgramData)[\\/]|AppData[\\/]/i.test(text)) fail(`Local Windows path in public file: ${file}`);
  if (!GENERATED.some((prefix) => file.startsWith(prefix)) && text.split("\n").length > LINE_BUDGET)
    fail(`${file} is over the ${LINE_BUDGET}-line budget`);
}

const pages = published.filter((file) => extname(file) === ".html");
for (const file of pages) {
  const html = readFileSync(join(root, file), "utf8");
  if (!/<title>[^<]+<\/title>/i.test(html)) fail(`${file} has no <title>`);
  const headings = (html.match(/<h1[\s>]/gi) || []).length;
  if (!NO_HEADING.includes(file) && headings !== 1) fail(`${file} has ${headings} <h1> elements`);
  for (const [, url] of html.matchAll(/\s(?:href|src)="([^"]+)"/gi)) {
    if (/^(?:[a-z]+:|\/\/|#|\$\{)/i.test(url)) continue;
    const path = url.split(/[?#]/)[0];
    if (!path) continue;
    const target = normalize(join(path.startsWith("/") ? site : dirname(join(root, file)), path));
    const resolved = existsSync(target) && statSync(target).isDirectory() ? join(target, "index.html") : target;
    if (!resolved.startsWith(site) || !existsSync(resolved)) fail(`${file}: broken link ${url}`);
  }
}

// Smoke: serve docs/ and request every page
const types = { ".html": "text/html", ".css": "text/css", ".js": "text/javascript" };
const server = createServer((request, response) => {
  let path = normalize(join(site, decodeURIComponent(new URL(request.url, "http://x").pathname)));
  if (existsSync(path) && statSync(path).isDirectory()) path = join(path, "index.html");
  if (!path.startsWith(site) || !existsSync(path)) return response.writeHead(404).end();
  response.writeHead(200, { "Content-Type": types[extname(path)] || "application/octet-stream" });
  response.end(readFileSync(path));
});
await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const { port } = server.address();
for (const file of pages) {
  const route = "/" + relative(site, join(root, file)).split(sep).join("/");
  const response = await fetch(`http://127.0.0.1:${port}${route}`);
  if (response.status !== 200) fail(`GET ${route} returned ${response.status}`);
}
server.close();

if (failures.length) {
  console.error(`verify failed (${failures.length}):\n- ${failures.join("\n- ")}`);
  process.exit(1);
}
console.log(`verify passed: ${tracked.length} tracked files, ${pages.length} pages served`);
